import contextlib
import io
import json
import os
import sys
import unittest
from unittest import mock

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
PYTHON_DIR = os.path.join(ROOT, "python")
if PYTHON_DIR not in sys.path:
    sys.path.insert(0, PYTHON_DIR)

import server as server_module
from server import Client, Server
from serviceManager import TextServiceManager

FIXTURE_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "wire-fixtures.json")

with open(FIXTURE_PATH, encoding="utf-8") as fixture_file:
    FIXTURE = json.load(fixture_file)

PROTOCOL = FIXTURE["protocol"]
CLIENT_ID = FIXTURE["clientId"]
GUID = FIXTURE["guid"]["python"]
UNKNOWN_GUID = FIXTURE["unknownGuid"]
# Every key a reply may carry: the names the C++ client reads, plus the ones
# only one backend adds (the go backend's `error`).
DECLARED_KEYS = set(FIXTURE["replyKeys"]) | set(FIXTURE["extraKeys"])


def resolve(value):
    """Replaces the fixture's guid sentinels with this adapter's own values."""
    if isinstance(value, dict):
        return {key: resolve(item) for key, item in value.items()}
    if isinstance(value, list):
        return [resolve(item) for item in value]
    if value == "$guid":
        return GUID
    if value == "$unknownGuid":
        return UNKNOWN_GUID
    return value


def fold(value):
    """Normalizes the `return` key, which python/node write as booleans and go as 1/0."""
    if value is True:
        return 1
    if value is False:
        return 0
    return value


class FakeService:
    """Minimal stand-in for a text service, used by the two cases that need a raising hook."""

    def __init__(self, client, guid):
        self.client = client
        self.guid = guid
        self.currentReply = {}
        self.requests = []

    def handleRequest(self, msg):
        if msg.get("method") == "boom":
            raise RuntimeError("service failure")
        self.requests.append(msg)
        self.currentReply = {}
        return {
            "success": True,
            "seqNum": msg.get("seqNum", 0),
            "return": msg.get("echo"),
        }


class FakeServiceManager:
    def __init__(self):
        self.created = []

    def createService(self, client, guid):
        if guid == "{00000000-0000-0000-0000-000000000000}":
            return None
        service = FakeService(client, guid)
        self.created.append(service)
        return service


def make_server():
    """Builds a Server over the shipped input-method directory, as main() does."""
    server = Server.__new__(Server)
    server.clients = {}
    server.serviceMgr = TextServiceManager()
    server.serviceMgr.load(PYTHON_DIR)
    return server


def make_fake_server():
    server = Server.__new__(Server)
    server.clients = {}
    server.serviceMgr = FakeServiceManager()
    return server


def run_lines(server, lines):
    """Runs Server.run() over a fixed line sequence and captures both streams."""
    stdout = io.StringIO()
    stderr = io.StringIO()
    with mock.patch("builtins.input", side_effect=list(lines) + [EOFError()]), \
         contextlib.redirect_stdout(stdout), \
         contextlib.redirect_stderr(stderr), \
         mock.patch.object(server_module, "append_error_log", lambda message: None):
        server.run()
    return stdout.getvalue(), stderr.getvalue()


def frame(payload):
    return f"{CLIENT_ID}|{json.dumps(payload)}"


def replies(output):
    """The (client_id, payload) pairs of the PIME_MSG lines, in order."""
    result = []
    for line in output.splitlines():
        if line.startswith(PROTOCOL["prefix"] + PROTOCOL["separator"]):
            _, client_id, payload = line.split(PROTOCOL["separator"], maxsplit=2)
            result.append((client_id, json.loads(payload)))
    return result


def run_case(case):
    """Plays one fixture case against a fresh session and returns the reply pairs."""
    server = make_server()
    lines = [
        step["raw"] if "raw" in step else frame(resolve(step["request"]))
        for step in case["steps"]
    ]
    output, _ = run_lines(server, lines)
    return server, output, replies(output)


class ServerWireFixtureTests(unittest.TestCase):
    """Every case of tests/wire-fixtures.json, played against the python backend."""


def _make_case_test(case):
    def test(self):
        _, output, received = run_case(case)
        index = 0
        for step in case["steps"]:
            if step["reply"] is None:
                self.assertEqual(index, len(received),
                                 f"{case['name']}: this frame must produce no reply")
                continue
            self.assertLess(index, len(received), f"{case['name']}: missing reply")
            client_id, payload = received[index]
            index += 1
            self.assertEqual(client_id, CLIENT_ID, f"{case['name']}: client id")
            for key, expected in step["reply"].items():
                self.assertIn(key, payload, f"{case['name']}: reply lacks {key}")
                self.assertEqual(fold(payload[key]), fold(expected),
                                 f"{case['name']}: {key}")
            for key in payload:
                self.assertIn(key, DECLARED_KEYS, f"{case['name']}: undeclared key {key}")
        self.assertEqual(index, len(received), f"{case['name']}: extra replies")
        # The backend writes its replies with ensure_ascii=False.
        self.assertNotIn("\\u", output, f"{case['name']}: non-ASCII must not be escaped")
    return test


for _index, _case in enumerate(FIXTURE["cases"], start=1):
    setattr(ServerWireFixtureTests,
            f"test_{_index:02d}_{_case['name']}",
            _make_case_test(_case))


class ServerProtocolTests(unittest.TestCase):
    """The framing constants and the session state the fixture cannot see."""

    def test_protocol_frames_are_the_documented_forms(self):
        self.assertEqual(PROTOCOL["request"], "<client_id>|<json>")
        self.assertEqual(PROTOCOL["reply"], "PIME_MSG|<client_id>|<json>")
        self.assertEqual(PROTOCOL["prefix"], "PIME_MSG")
        self.assertEqual(PROTOCOL["separator"], "|")
        self.assertEqual(PROTOCOL["maxsplit"], 1)
        self.assertTrue(PROTOCOL["echoesSeqNum"])

    def test_reply_line_keeps_the_prefix_and_the_first_split(self):
        # A payload carrying '|' must survive the split, so the reply is cut at
        # the first separator after the prefix and nothing else is rewritten.
        server = make_server()
        output, _ = run_lines(server, [
            frame(resolve(FIXTURE["cases"][0]["steps"][0]["request"])),
            frame({"method": "onCommand", "seqNum": 8, "id": "x|y", "type": 2}),
        ])
        lines = [line for line in output.splitlines() if line.startswith("PIME_MSG|")]
        self.assertEqual(len(lines), 2)
        for line in lines:
            self.assertTrue(line.startswith(f"PIME_MSG|{CLIENT_ID}|"))
        self.assertEqual(replies(output)[1][1]["seqNum"], 8)

    def test_nested_reply_maps_use_the_declared_key_names(self):
        # onActivate is the case whose reply carries the nested maps, so the
        # declared uiKeys/buttonKeys lists are pinned against the real service.
        case = next(item for item in FIXTURE["cases"] if item["name"] == "onActivate")
        _, _, received = run_case(case)
        activate = received[-1][1]
        self.assertIn("customizeUI", activate)
        self.assertLessEqual(set(activate["customizeUI"]), set(FIXTURE["uiKeys"]))
        self.assertIn("addButton", activate)
        for button in activate["addButton"]:
            self.assertLessEqual(set(button), set(FIXTURE["buttonKeys"]))
        self.assertIn("setSelKeys", activate)

    def test_service_exception_is_reported_and_loop_continues(self):
        server = make_fake_server()
        output, _ = run_lines(server, [
            frame({"method": "init", "id": GUID, "seqNum": 0, "isWindows8Above": True,
                   "isMetroApp": False, "isUiLess": False, "isConsole": False}),
            frame({"method": "boom", "seqNum": 4}),
            frame({"method": "filterKeyDown", "seqNum": 5, "echo": "still-alive"}),
        ])

        self.assertEqual(replies(output), [
            (CLIENT_ID, {"success": True, "seqNum": 0}),
            (CLIENT_ID, {"success": False, "seqNum": 4}),
            (CLIENT_ID, {"success": True, "seqNum": 5, "return": "still-alive"}),
        ])
        self.assertEqual(server.clients[CLIENT_ID].service.currentReply, {})

    def test_close_removes_the_client_session(self):
        server = make_server()
        run_lines(server, [
            frame(resolve(FIXTURE["cases"][0]["steps"][0]["request"])),
            frame({"method": "close", "seqNum": 3}),
        ])

        self.assertNotIn(CLIENT_ID, server.clients)

    def test_clients_are_isolated(self):
        server = make_server()
        init = frame(resolve(FIXTURE["cases"][0]["steps"][0]["request"]))
        output, _ = run_lines(server, [init, init.replace(CLIENT_ID + "|", "other|", 1)])

        self.assertEqual([client_id for client_id, _ in replies(output)],
                         [CLIENT_ID, "other"])
        self.assertIsInstance(server.clients[CLIENT_ID], Client)
        self.assertIsNot(server.clients[CLIENT_ID].service,
                         server.clients["other"].service)

    def test_init_stores_client_flags(self):
        server = make_server()
        payload = resolve(FIXTURE["cases"][0]["steps"][0]["request"])
        payload.update({"isWindows8Above": False, "isMetroApp": True,
                        "isUiLess": True, "isConsole": True})
        run_lines(server, [frame(payload)])

        client = server.clients[CLIENT_ID]
        self.assertFalse(client.isWindows8Above)
        self.assertTrue(client.isMetroApp)
        self.assertTrue(client.isUiLess)
        self.assertTrue(client.isConsole)


